#!/usr/bin/env python
"""Regenerate docs/reference/config.md from the Settings dataclass.

Every config key, its default and its doc live on one field in
``realm/config/loader.py``. Run after adding or changing one:

    python scripts/gen_config_docs.py
"""
from __future__ import annotations

import pathlib
from dataclasses import MISSING, fields

from realm.config.loader import Settings

OUT = pathlib.Path(__file__).resolve().parent.parent / "docs" / "reference" / "config.md"

HEADER = """# Configuration reference

<!-- Generated by scripts/gen_config_docs.py from realm/config/loader.py. Do not edit by hand. -->

A game is configured by `config.py` in its game directory. Every key below is
optional; an unset key takes its default. A relative path is resolved against
the game directory. A key that is a near miss of a real one (`WELCOME_BANER`)
logs a warning at boot, because it would otherwise be ignored. Other UPPERCASE
names are yours: `init_world` can read them with `server.settings.get("NAME")`.

## Keys

| Key | Default | What it does |
|---|---|---|
"""

FEATURE_KEYS = """
## Keys declared by built-in features

A feature can declare its own keys. These exist only when the feature is in
`FEATURES` (all of them are by default).

| Key | Feature | Default | What it does |
|---|---|---|---|
"""

CALLBACKS = """
## Callbacks

Define a function with one of these names in `config.py` and the server
calls it.

| Function | What it does |
|---|---|
"""


def _default(f) -> str:
    return _value(f.default if f.default is not MISSING else None)


def _value(value) -> str:
    if isinstance(value, pathlib.Path):
        value = str(value)
    text = "`None`" if value is None else f"`{value!r}`"
    return text.replace("|", "\\|")


def _cell(text: str) -> str:
    return " ".join(text.split()).replace("|", "\\|")


def render() -> str:
    keys = [f for f in fields(Settings) if "key" in f.metadata]
    callbacks = [f for f in fields(Settings) if f.metadata.get("callback")]
    rows = [f"| `{f.metadata['key']}` | {_default(f)} | {_cell(f.metadata['doc'])} |"
            for f in keys]
    callback_rows = [f"| `{f.name}` | {_cell(f.metadata['doc'])} |" for f in callbacks]
    from realm.features import load
    from realm.std import CLASSIC
    declared = load(CLASSIC).settings
    feature_rows = [
        f"| `{key}` | `{feature}` | {_value(default)} | {_cell(doc)} |"
        for key, (default, doc, feature) in declared.items()]
    return (HEADER + "\n".join(rows) + "\n" + FEATURE_KEYS + "\n".join(feature_rows)
            + "\n" + CALLBACKS + "\n".join(callback_rows) + "\n")


def main() -> None:
    OUT.write_text(render(), encoding="utf-8")
    print(f"wrote {OUT} ({sum('key' in f.metadata for f in fields(Settings))} keys)")


if __name__ == "__main__":
    main()
